import { test } from "node:test";
import assert from "node:assert/strict";
import { createCounter } from "../src/counter.js";

test("初期値は0", () => {
  const c = createCounter();
  assert.equal(c.getValue(), 0);
});

test("incrementで1ずつ増える", () => {
  const c = createCounter();
  c.increment();
  c.increment();
  assert.equal(c.getValue(), 2);
});

test("decrementで減る(マイナスも可)", () => {
  const c = createCounter();
  c.decrement();
  assert.equal(c.getValue(), -1);
});

test("resetで0に戻る", () => {
  const c = createCounter();
  c.increment();
  c.increment();
  c.reset();
  assert.equal(c.getValue(), 0);
});

test("増減後もresetが効く", () => {
  const c = createCounter();
  c.decrement();
  c.increment();
  c.increment();
  c.reset();
  c.increment();
  assert.equal(c.getValue(), 1);
});
